/* ==UserStyle==
@name Tuta Catppuccin
@namespace github.com/catppuccin/userstyles/styles/tuta
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/tuta
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/tuta/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Atuta
@description Soothing pastel theme for Tuta
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("app.tuta.com"), domain("mail.tutanota.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body,
    drawer-menu,
    .list-bg {
      background-color: @mantle !important;
      color: @text;
    }

    .list-row {
      background-color: @base;
    }
    .odd-row {
      background-color: @surface0;
    }

    .header-nav {
      background-color: @base;
    }

    .elevated-bg,
    .folder-column,
    div[aria-modal] {
      background-color: @base !important;
    }

    .icon {
      &[style*="fill: rgb(78, 78, 78);"] {
        fill: @text !important;
      }

      &[style*="fill: rgb(174, 174, 174);"] {
        fill: @subtext0 !important;
      }

      &[style*="fill: rgb(255, 83, 83);"] {
        fill: @accent !important;
      }
    }

    .h2 {
      color: @subtext1 !important;
    }

    .bottom-nav {
      background: @mantle !important;
      color: @text !important;
    }

    .dropdown-button,
    .dropdown-button div {
      color: @text !important;
    }
    .dropdown-button:hover {
      background-color: @surface1 !important;
    }

    /* logo */
    path[style*="fill: #00d2a7;"] {
      fill: @accent !important;
    }

    path[style*="fill: #c5c7c7;"] {
      fill: @text !important;
    }

    .row-selected {
      border-color: @accent !important;
      color: @accent !important;
    }
    .row-selected > .nav-button {
      color: @accent !important;

      > .icon {
        fill: @accent !important;
      }
    }

    .secondary {
      color: @accent !important;
    }

    .nav-button,
    .sidebar-section.mb {
      color: @subtext0 !important;
    }

    .bubble {
      background-color: @base;
      color: @text;
    }

    :where(.mouse-nav) .state-bg:hover,
    :where(.keyboard-nav) .state-bg:hover,
    [style*="background: rgba(139, 139, 139, 0.22)"] {
      background-color: @surface0 !important;
    }

    .nav-bg,
    .content-bg,
    [style*="background-color: rgb(35, 35, 35)"] {
      background-color: @base !important;
    }
    [style*="background-color: rgb(17, 17, 17);"] {
      background-color: @mantle !important;
    }
    [style*="background-color: rgba(139, 139, 139, 0.22);"] {
      background-color: @surface0 !important;
    }
    [style*="background-color: rgba(139, 139, 139, 0.38);"] {
      background-color: @surface1 !important;
    }

    [style*="color: rgb(221, 221, 221);"] {
      color: @text !important;
    }

    [style*="color: rgb(174, 174, 174);"] {
      color: @subtext1 !important;
    }

    .teamLabel {
      background-color: @accent;
      color: @mantle;
    }

    [style*="border: 2px solid rgb(255, 83, 83);"] {
      border-color: @accent !important;
    }
    [style*="color: rgb(255, 83, 83);"],
    .content-accent-fg {
      color: @accent !important;
    }

    button.expander {
      color: @subtext0 !important;
    }

    .logo-height > svg:nth-child(1) > path:nth-child(2) {
      fill: @accent !important;
    }

    ::-webkit-scrollbar-thumb {
      background-color: @surface1;
    }
  }
}

